// Lo que sale del nodo HTML es texto: lo pasamos a números y a enlaces completos.
// Los enlaces de la página son relativos a su carpeta:
// en «https://books.toscrape.com/catalogue/page-2.html» la carpeta es «https://books.toscrape.com/catalogue/».
let url = String($('Qué página leer').first().json.url).trim();
if (/^https?:\/\/[^/]+$/.test(url)) url += '/';
const base = url.slice(0, url.lastIndexOf('/') + 1);
const ESTRELLAS = { One: 1, Two: 2, Three: 3, Four: 4, Five: 5 };

return $input.all().map((item) => {
  const libro = item.json;
  // «star-rating Three» → «Three» → 3
  const palabra = String(libro.estrellas ?? '').replace('star-rating', '').trim();
  // «£51.77» → 51.77 (sacamos todo lo que no sea número o punto)
  const precio = Number(String(libro.precio ?? '').replace(/[^0-9.]/g, ''));
  const enlace = String(libro.enlace ?? '');
  return {
    json: {
      titulo: libro.titulo,
      precio_libras: precio,
      estrellas: ESTRELLAS[palabra] ?? 0,
      disponible: /in stock/i.test(libro.disponibilidad ?? ''),
      enlace: enlace.startsWith('http') ? enlace : base + enlace,
    },
  };
});
